INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-chem_q1', 'ap-diag-chem', 1, false, 'C', 'Structure', 'easy', 'Which subatomic particle defines the atomic number of an element?', '["Neutron","Electron","Proton","Positron"]'::jsonb, 'Atomic number is the number of protons.'),
  ('ap-diag-chem_q2', 'ap-diag-chem', 2, false, 'B', 'Atomic Structure', 'easy', 'How many protons does Carbon have?', '["4","6","8","12"]'::jsonb, 'Carbon''s atomic number is 6, meaning it has 6 protons.'),
  ('ap-diag-chem_q3', 'ap-diag-chem', 3, false, 'C', 'Periodic Trends', 'easy', 'Electronegativity generally _____ across a period left to right.', '["Decreases","Stays the same","Increases","Fluctuates randomly"]'::jsonb, 'Electronegativity increases across a period as nuclear charge increases with no new shells.'),
  ('ap-diag-chem_q4', 'ap-diag-chem', 4, false, 'B', 'Periodic Trends', 'easy', 'Atomic radius generally _____ going down a group.', '["Decreases","Increases","Stays constant","Cannot be predicted"]'::jsonb, 'Atomic radius increases down a group as additional electron shells are added.'),
  ('ap-diag-chem_q5', 'ap-diag-chem', 5, false, 'C', 'Bonding', 'easy', 'NaCl is an example of:', '["Covalent bond","Metallic bond","Ionic bond","Hydrogen bond"]'::jsonb, 'NaCl forms when Na+ and Cl- ions are electrostatically attracted — an ionic bond.'),
  ('ap-diag-chem_q6', 'ap-diag-chem', 6, false, 'B', 'Bonding', 'medium', 'H2O has bent molecular geometry because of:', '["2 bonding pairs only","2 lone pairs on oxygen","Linear arrangement of atoms","4 bonding pairs"]'::jsonb, 'Two lone pairs on oxygen repel bonding pairs, creating a bent shape (~104.5 degree bond angle).'),
  ('ap-diag-chem_q7', 'ap-diag-chem', 7, false, 'B', 'Stoichiometry', 'medium', 'How many moles are in 44 g of CO2? (Molar mass = 44 g/mol)', '["0.5","1","2","44"]'::jsonb, 'moles = mass/molar mass = 44/44 = 1 mol.'),
  ('ap-diag-chem_q8', 'ap-diag-chem', 8, false, 'B', 'Stoichiometry', 'medium', 'In 2H2 + O2 -> 2H2O, moles of H2O from 4 mol H2?', '["2","4","6","8"]'::jsonb, 'Mole ratio H2:H2O = 2:2 = 1:1. So 4 mol H2 produces 4 mol H2O.'),
  ('ap-diag-chem_q9', 'ap-diag-chem', 9, false, 'B', 'Gas Laws', 'medium', 'At constant temperature, if volume halves, pressure:', '["Halves","Doubles","Stays the same","Quadruples"]'::jsonb, 'Boyle''s Law: PV = constant. If V halves, P doubles.'),
  ('ap-diag-chem_q10', 'ap-diag-chem', 10, false, 'A', 'Gas Laws', 'medium', 'The Ideal Gas Law is:', '["PV = nRT","PV = RT","$P = nRT$","$V = nRT/R$"]'::jsonb, 'PV = nRT where P=pressure, V=volume, n=moles, R=gas constant, T=temperature in Kelvin.'),
  ('ap-diag-chem_q11', 'ap-diag-chem', 11, false, 'B', 'Thermodynamics', 'medium', 'An exothermic reaction:', '["Absorbs heat from surroundings","Releases heat to surroundings","Has delta-H > 0","Requires very high activation energy"]'::jsonb, 'Exothermic reactions release heat to surroundings; delta-H < 0.'),
  ('ap-diag-chem_q12', 'ap-diag-chem', 12, false, 'C', 'Thermodynamics', 'medium', 'A reaction is spontaneous when delta-G is:', '["Positive","Zero","Negative","Equal to delta-H"]'::jsonb, 'Spontaneous processes have delta-G < 0 (Gibbs free energy decreases).'),
  ('ap-diag-chem_q13', 'ap-diag-chem', 13, false, 'B', 'Equilibrium', 'medium', 'Le Chatelier''s principle states a system at equilibrium will:', '["Always shift right","Shift to oppose any imposed stress","Shift to increase products","Stay completely unchanged"]'::jsonb, 'Le Chatelier''s principle: a system at equilibrium shifts to counteract any stress imposed on it.'),
  ('ap-diag-chem_q14', 'ap-diag-chem', 14, false, 'B', 'Equilibrium', 'medium', 'Increasing temperature shifts an endothermic equilibrium toward:', '["Reactants","Products","Neither direction","Equilibrium constant K only"]'::jsonb, 'For endothermic reactions, heat is a reactant; adding heat shifts equilibrium toward products.'),
  ('ap-diag-chem_q15', 'ap-diag-chem', 15, false, 'C', 'Acids and Bases', 'easy', 'A solution with pH = 3 is:', '["Basic","Neutral","Acidic","Impossible"]'::jsonb, 'pH < 7 is acidic; pH = 7 is neutral; pH > 7 is basic.'),
  ('ap-diag-chem_q16', 'ap-diag-chem', 16, false, 'B', 'Acids and Bases', 'medium', 'A strong acid like HCl:', '["Partially dissociates in water","Completely dissociates in water","Does not react with water","Forms a buffer with its conjugate"]'::jsonb, 'Strong acids completely ionize in aqueous solution.'),
  ('ap-diag-chem_q17', 'ap-diag-chem', 17, false, 'C', 'Kinetics', 'medium', 'Increasing temperature increases reaction rate because:', '["Concentration increases","Activation energy barrier drops","More particles have sufficient energy to react","Equilibrium shifts right"]'::jsonb, 'Higher temperature gives more particles enough kinetic energy to overcome the activation energy barrier.'),
  ('ap-diag-chem_q18', 'ap-diag-chem', 18, false, 'C', 'Kinetics', 'hard', 'For a first-order reaction, the rate law is:', '["Rate = k[A]^2","Rate = k","Rate = k[A]","Rate = k[A][B]"]'::jsonb, 'A first-order reaction has rate proportional to the first power of the reactant concentration.'),
  ('ap-diag-chem_q19', 'ap-diag-chem', 19, false, 'B', 'Electrochemistry', 'medium', 'Oxidation occurs at the:', '["Cathode","Anode","Salt bridge","Membrane"]'::jsonb, 'Oxidation (loss of electrons) occurs at the anode; reduction occurs at the cathode.'),
  ('ap-diag-chem_q20', 'ap-diag-chem', 20, false, 'B', 'Electrochemistry', 'medium', 'In an electrolytic cell, electrical energy converts to:', '["Mechanical energy","Chemical energy","Thermal energy only","Nuclear energy"]'::jsonb, 'Electrolytic cells use electrical energy to drive non-spontaneous chemical reactions.'),
  ('ap-diag-chem_q21', 'ap-diag-chem', 21, false, 'A', 'Solutions', 'medium', 'Molarity is defined as:', '["Moles of solute per liter of solution","Grams of solute per liter","Moles per kilogram of solvent","Mass fraction of solute"]'::jsonb, 'Molarity (M) = moles of solute divided by liters of solution.'),
  ('ap-diag-chem_q22', 'ap-diag-chem', 22, false, 'C', 'Solutions', 'medium', 'Adding a non-volatile solute to a solvent _____ the boiling point.', '["Decreases","Does not affect","Increases","Makes it exactly 100 C"]'::jsonb, 'Boiling point elevation is a colligative property — adding solute raises the boiling point.'),
  ('ap-diag-chem_q23', 'ap-diag-chem', 23, false, 'B', 'Nuclear Chemistry', 'medium', 'Alpha decay emits:', '["An electron","A helium-4 nucleus","A gamma photon","A neutron"]'::jsonb, 'Alpha particles are helium-4 nuclei (2 protons + 2 neutrons).'),
  ('ap-diag-chem_q24', 'ap-diag-chem', 24, false, 'B', 'Nuclear Chemistry', 'medium', 'In beta-minus decay, the atomic number:', '["Decreases by 1","Increases by 1","Stays the same","Decreases by 2"]'::jsonb, 'Beta-minus decay converts a neutron to a proton, increasing atomic number by 1.'),
  ('ap-diag-chem_q25', 'ap-diag-chem', 25, false, 'B', 'Organic Chemistry', 'easy', 'The functional group -OH indicates:', '["Aldehyde","Alcohol","Carboxylic acid","Ether"]'::jsonb, '-OH is the hydroxyl group, characteristic of alcohols.'),
  ('ap-diag-chem_q26', 'ap-diag-chem', 26, false, 'B', 'Atomic Structure', 'medium', 'The Heisenberg uncertainty principle states:', '["Energy is quantized","Position and momentum cannot both be precisely known simultaneously","Light behaves as a wave only","Electrons orbit in fixed circular paths"]'::jsonb, 'It is fundamentally impossible to simultaneously know both the exact position and momentum of a particle.'),
  ('ap-diag-chem_q27', 'ap-diag-chem', 27, false, 'D', 'Intermolecular Forces', 'medium', 'Which intermolecular force is generally the strongest?', '["London dispersion","Dipole-dipole","Hydrogen bonding","Ion-dipole"]'::jsonb, 'Ion-dipole forces are the strongest intermolecular forces, followed by hydrogen bonding.'),
  ('ap-diag-chem_q28', 'ap-diag-chem', 28, false, 'C', 'Bonding', 'hard', 'sp2 hybridization results in bond angles of approximately:', '["90 degrees","109.5 degrees","120 degrees","180 degrees"]'::jsonb, 'sp2 hybridization results in trigonal planar geometry with 120 degree bond angles.'),
  ('ap-diag-chem_q29', 'ap-diag-chem', 29, false, 'B', 'Stoichiometry', 'hard', '10 g of H2 reacts with excess O2 to form H2O. Grams of H2O formed? (H2=2 g/mol, H2O=18 g/mol)', '["18 g","90 g","10 g","45 g"]'::jsonb, '10 g H2 = 5 mol H2. Ratio H2:H2O = 1:1, so 5 mol H2O = 5 * 18 = 90 g.'),
  ('ap-diag-chem_q30', 'ap-diag-chem', 30, false, 'C', 'Thermodynamics', 'hard', 'A reaction with delta-H < 0 and delta-S > 0 is:', '["Always non-spontaneous","Spontaneous only at high T","Always spontaneous at all temperatures","Spontaneous only at low T"]'::jsonb, 'When delta-H < 0 and delta-S > 0, delta-G = delta-H - T*delta-S < 0 at all temperatures — always spontaneous.'),
  ('ap-diag-bio_q1', 'ap-diag-bio', 1, false, 'B', 'Cells', 'easy', 'Which organelle is responsible for cellular respiration and ATP production?', '["Ribosome","Mitochondria","Golgi apparatus","Lysosome"]'::jsonb, 'Mitochondria generates ATP through cellular respiration.'),
  ('ap-diag-bio_q2', 'ap-diag-bio', 2, false, 'C', 'Cell Structure', 'easy', 'Which organelle is the powerhouse of the cell?', '["Nucleus","Ribosome","Mitochondria","Golgi apparatus"]'::jsonb, 'Mitochondria produce ATP through cellular respiration.'),
  ('ap-diag-bio_q3', 'ap-diag-bio', 3, false, 'C', 'Cell Structure', 'easy', 'The cell membrane is primarily composed of:', '["Proteins only","DNA","Phospholipid bilayer","Carbohydrates"]'::jsonb, 'The cell membrane consists of a phospholipid bilayer with embedded proteins.'),
  ('ap-diag-bio_q4', 'ap-diag-bio', 4, false, 'C', 'DNA', 'easy', 'DNA replication follows which model?', '["Conservative","Dispersive","Semi-conservative","Random"]'::jsonb, 'Semi-conservative replication: each new DNA molecule has one original and one new strand.'),
  ('ap-diag-bio_q5', 'ap-diag-bio', 5, false, 'B', 'Transcription', 'medium', 'During transcription, DNA is used as a template to produce:', '["Proteins","mRNA","A DNA copy","Ribosomes"]'::jsonb, 'Transcription produces messenger RNA (mRNA) from a DNA template.'),
  ('ap-diag-bio_q6', 'ap-diag-bio', 6, false, 'B', 'Central Dogma', 'medium', 'The central dogma of molecular biology states:', '["RNA -> DNA -> Protein","DNA -> RNA -> Protein","Protein -> DNA -> RNA","DNA -> Protein directly"]'::jsonb, 'The central dogma: DNA is transcribed to RNA, which is translated to protein.'),
  ('ap-diag-bio_q7', 'ap-diag-bio', 7, false, 'B', 'Evolution', 'easy', 'Natural selection acts on:', '["Genotypes only","Phenotypes","Random mutations only","Gene pools uniformly"]'::jsonb, 'Natural selection acts on phenotypes (observable traits), not directly on genotypes.'),
  ('ap-diag-bio_q8', 'ap-diag-bio', 8, false, 'C', 'Evolution', 'medium', 'Which of the following provides evidence for evolution?', '["Only fossil records","Only DNA comparisons","Fossils, comparative anatomy, embryology, and DNA","Only observed mutations"]'::jsonb, 'Multiple lines of evidence support evolution: fossils, comparative anatomy, embryology, and molecular data.'),
  ('ap-diag-bio_q9', 'ap-diag-bio', 9, false, 'C', 'Ecology', 'easy', 'Producers in an ecosystem are:', '["Herbivores","Carnivores","Photosynthetic organisms","Decomposers"]'::jsonb, 'Producers (autotrophs) make their own food via photosynthesis, forming the base of food webs.'),
  ('ap-diag-bio_q10', 'ap-diag-bio', 10, false, 'B', 'Ecology', 'medium', 'The 10% rule in energy transfer means:', '["10% of species survive","Only 10% of energy moves to the next trophic level","10% of producers are consumed","10% of sunlight reaches earth"]'::jsonb, 'Only ~10% of energy transfers from one trophic level to the next; 90% is lost as heat.'),
  ('ap-diag-bio_q11', 'ap-diag-bio', 11, false, 'C', 'Photosynthesis', 'medium', 'In which organelle does photosynthesis occur?', '["Mitochondria","Nucleus","Chloroplast","Ribosome"]'::jsonb, 'Photosynthesis takes place in the chloroplasts of plant and algal cells.'),
  ('ap-diag-bio_q12', 'ap-diag-bio', 12, false, 'B', 'Photosynthesis', 'medium', 'The light-dependent reactions produce:', '["Glucose only","ATP and NADPH","CO2 and H2O","Only water"]'::jsonb, 'Light-dependent reactions produce ATP, NADPH, and O2 using light energy and water.'),
  ('ap-diag-bio_q13', 'ap-diag-bio', 13, false, 'C', 'Cell Respiration', 'medium', 'Aerobic respiration produces approximately how many ATP from one glucose?', '["2","10","38","100"]'::jsonb, 'Complete aerobic respiration yields approximately 36-38 ATP per glucose molecule.'),
  ('ap-diag-bio_q14', 'ap-diag-bio', 14, false, 'C', 'Cell Respiration', 'medium', 'Glycolysis takes place in the:', '["Mitochondrial matrix","Chloroplast","Cytoplasm","Nucleus"]'::jsonb, 'Glycolysis, the first step of cellular respiration, occurs in the cytoplasm.'),
  ('ap-diag-bio_q15', 'ap-diag-bio', 15, false, 'A', 'Genetics', 'medium', 'If both parents are Aa, what fraction of offspring will be aa?', '["$\\frac{1}{4}$","$\\frac{1}{2}$","$\\frac{3}{4}$","0"]'::jsonb, 'Punnett square: AA (1/4), Aa (2/4), aa (1/4). So 25% are homozygous recessive.'),
  ('ap-diag-bio_q16', 'ap-diag-bio', 16, false, 'B', 'Genetics', 'medium', 'A dominant allele is expressed:', '["Only when two copies are present","Even when only one copy is present","Only in females","Only when recessive alleles are absent entirely"]'::jsonb, 'Dominant alleles are expressed in both heterozygous and homozygous dominant conditions.'),
  ('ap-diag-bio_q17', 'ap-diag-bio', 17, false, 'B', 'Cell Division', 'medium', 'During which phase of mitosis do chromosomes line up at the equator?', '["Prophase","Metaphase","Anaphase","Telophase"]'::jsonb, 'During metaphase, chromosomes align at the metaphase plate (cell''s equator).'),
  ('ap-diag-bio_q18', 'ap-diag-bio', 18, false, 'B', 'Cell Division', 'medium', 'Meiosis produces:', '["2 identical diploid cells","4 genetically diverse haploid cells","2 haploid cells","4 identical diploid cells"]'::jsonb, 'Meiosis produces 4 haploid gametes that are genetically unique due to crossing over and independent assortment.'),
  ('ap-diag-bio_q19', 'ap-diag-bio', 19, false, 'D', 'Animal Physiology', 'medium', 'Which blood vessel carries oxygenated blood away from the heart to the body?', '["Veins","Capillaries","Pulmonary artery","Aorta"]'::jsonb, 'The aorta carries oxygenated blood from the left ventricle to the rest of the body.'),
  ('ap-diag-bio_q20', 'ap-diag-bio', 20, false, 'B', 'Animal Physiology', 'medium', 'The main function of the kidneys is:', '["Gas exchange","Blood filtration and waste excretion","Hormone production only","Digestion of nutrients"]'::jsonb, 'Kidneys filter blood, regulate water balance, and excrete metabolic wastes as urine.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-bio_q21', 'ap-diag-bio', 21, false, 'C', 'Plant Biology', 'medium', 'Water moves up a plant stem primarily via:', '["Active transport by roots","Osmosis only","Transpiration-cohesion-tension mechanism","Gravity"]'::jsonb, 'Water is pulled up through xylem by the cohesion-tension mechanism driven by transpiration from leaves.'),
  ('ap-diag-bio_q22', 'ap-diag-bio', 22, false, 'C', 'Ecology', 'hard', 'Commensalism describes the relationship where:', '["Both species benefit","One benefits, one harmed","One benefits, other unaffected","Both are harmed"]'::jsonb, 'Commensalism: one organism benefits (+) and the other is unaffected (0).'),
  ('ap-diag-bio_q23', 'ap-diag-bio', 23, false, 'B', 'Biochemistry', 'medium', 'Enzymes speed up reactions by:', '["Increasing temperature","Lowering activation energy","Providing additional energy","Increasing substrate concentration"]'::jsonb, 'Enzymes are biological catalysts that lower the activation energy needed for a reaction to proceed.'),
  ('ap-diag-bio_q24', 'ap-diag-bio', 24, false, 'D', 'Biochemistry', 'medium', 'Which macromolecule is the primary immediate energy source for cells?', '["Proteins","Nucleic acids","Lipids","Carbohydrates"]'::jsonb, 'Carbohydrates (especially glucose) are the primary immediate energy source for cellular processes.'),
  ('ap-diag-bio_q25', 'ap-diag-bio', 25, false, 'B', 'Immune System', 'medium', 'B cells in the immune system produce:', '["T cells","Antibodies","Antigens","Phagocytes"]'::jsonb, 'B lymphocytes differentiate into plasma cells that secrete antibodies targeting specific antigens.'),
  ('ap-diag-bio_q26', 'ap-diag-bio', 26, false, 'B', 'Nervous System', 'medium', 'An action potential fires when the membrane reaches:', '["Resting potential","Threshold potential","Hyperpolarization peak","Repolarization point"]'::jsonb, 'When threshold potential (~-55 mV) is reached, voltage-gated Na+ channels open triggering the action potential.'),
  ('ap-diag-bio_q27', 'ap-diag-bio', 27, false, 'C', 'Evolution', 'hard', 'Hardy-Weinberg equilibrium requires all EXCEPT:', '["Random mating","No natural selection","No genetic drift","No migration"]'::jsonb, 'Hardy-Weinberg equilibrium assumes large populations with NO genetic drift — drift violates the equilibrium.'),
  ('ap-diag-bio_q28', 'ap-diag-bio', 28, false, 'B', 'Cell Signaling', 'hard', 'Signal transduction pathways convert:', '["DNA to RNA","Extracellular signals to intracellular responses","mRNA to proteins","Nutrients to ATP"]'::jsonb, 'Signal transduction pathways relay and amplify extracellular signals into appropriate cellular responses.'),
  ('ap-diag-bio_q29', 'ap-diag-bio', 29, false, 'B', 'Genetics', 'hard', 'Crossing over during meiosis increases:', '["Chromosome number","Genetic diversity","Mutation rate","Cell cycle speed"]'::jsonb, 'Crossing over (recombination) between homologous chromosomes creates new allele combinations, increasing genetic diversity.'),
  ('ap-diag-bio_q30', 'ap-diag-bio', 30, false, 'B', 'Ecology', 'hard', 'Primary succession begins on:', '["Disturbed ecosystems with remaining soil","Bare rock with no existing soil","Flooded grasslands","Burned forests with some soil"]'::jsonb, 'Primary succession starts on bare substrate (like bare rock after a glacier retreats) with no existing soil.'),
  ('ap-topic-bio-chem_q1', 'ap-topic-bio-chem', 1, false, 'B', 'Cell Energetics', 'easy', 'Which organelle is the primary site of ATP synthesis during aerobic cellular respiration?', '["Ribosome","Mitochondrion","Chloroplast","Golgi Apparatus"]'::jsonb, 'Mitochondria generate ATP via oxidative phosphorylation.'),
  ('ap-topic-bio-chem_q2', 'ap-topic-bio-chem', 2, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'How do hydrogen bonds contribute to the unique emergent properties of liquid water essential for living organisms?', '["They produce high cohesion, surface tension, and high specific heat capacity that moderates temperature fluctuations","They cause water to become more dense as a solid than as a liquid","They prevent water from acting as a biological solvent for polar solutes","They form permanent covalent bonds between separate water molecules"]'::jsonb, 'Polarity allows water molecules to form transient hydrogen bonds, conferring high specific heat, high heat of vaporization, strong cohesion/adhesion, and expansion upon freezing (ice floats).'),
  ('ap-topic-bio-chem_q3', 'ap-topic-bio-chem', 3, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'Which functional group is primarily responsible for forming disulfide bridges that stabilize the tertiary structure of proteins?', '["Sulfhydryl group (-SH) in cysteine","Carboxyl group (-COOH) in aspartic acid","Amino group (-NH2) in lysine","Hydroxyl group (-OH) in serine"]'::jsonb, 'Covalent disulfide bridges form through the oxidation of two sulfhydryl (-SH) groups on adjacent cysteine amino acid residues, stabilizing tertiary and quaternary protein conformations.'),
  ('ap-topic-bio-chem_q4', 'ap-topic-bio-chem', 4, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'In enzyme kinetics, how does a competitive inhibitor affect $V_{\max}$ and $K_m$?', '["$V_{\\max}$ remains unchanged; $K_m$ increases","$V_{\\max}$ decreases; $K_m$ remains unchanged","Both $V_{\\max}$ and $K_m$ decrease","Both $V_{\\max}$ and $K_m$ increase"]'::jsonb, 'A competitive inhibitor binds reversibly to the active site. Increasing substrate concentration outcompetes the inhibitor, so the maximum velocity $V_{\max}$ is unchanged, but higher substrate concentration is needed to reach $\frac{1}{2}V_{\max}$, increasing apparent $K_m$.'),
  ('ap-topic-bio-chem_q5', 'ap-topic-bio-chem', 5, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'During oxidative phosphorylation in mitochondria, what immediately drives the synthesis of ATP by ATP synthase?', '["The flow of protons down an electrochemical gradient from the intermembrane space into the mitochondrial matrix","The direct transfer of phosphate groups from glucose intermediates to ADP","The oxidation of molecular oxygen into water in the cytosol","The active pumping of sodium ions across the outer mitochondrial membrane"]'::jsonb, 'Chemiosmosis utilizes the proton-motive force: protons ($H^+$) accumulated in the intermembrane space flow down their electrochemical gradient through the $F_0$ rotor of ATP synthase into the matrix, driving ATP phosphorylation.'),
  ('ap-topic-bio-chem_q6', 'ap-topic-bio-chem', 6, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'What is the immediate source of electrons that replace those excited and ejected from chlorophyll P680 in Photosystem II during oxygenic photosynthesis?', '["Water ($H_2O$)","NADPH","Carbon dioxide ($CO_2$)","Glucose"]'::jsonb, 'The oxygen-evolving complex of Photosystem II photolyzes water ($2H_2O \to 4H^+ + 4e^- + O_2$), supplying replacement electrons to the P680 reaction center and releasing $O_2$ as a byproduct.'),
  ('ap-topic-bio-chem_q7', 'ap-topic-bio-chem', 7, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'A red blood cell with an internal osmolarity of 300 mOsm is placed in a beaker containing a 100 mOsm NaCl solution. What will happen to the cell?', '["Water will enter the cell by osmosis, causing it to swell and potentially lyse","Water will leave the cell, causing it to shrivel (crenate)","NaCl will actively exit the cell until equilibrium is reached","There will be no net movement of water because the membrane is impermeable"]'::jsonb, 'The external 100 mOsm solution is hypotonic relative to the 300 mOsm cytoplasm. Water diffuses down its water potential gradient into the cell, swelling and potentially lysing the red blood cell.'),
  ('ap-topic-bio-chem_q8', 'ap-topic-bio-chem', 8, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'What occurs during the Calvin cycle in the chloroplast stroma?', '["$CO_2$ is fixed by RuBisCO to ribulose-1,5-bisphosphate (RuBP), then reduced using ATP and NADPH to produce G3P","Photons excite electrons to generate ATP and NADPH","Pyruvate is decarboxylated to form acetyl-CoA","Water molecules are split into oxygen and protons"]'::jsonb, 'The Calvin cycle consists of carbon fixation (catalyzed by RuBisCO binding $CO_2$ to RuBP), reduction (using ATP and NADPH to form G3P), and regeneration of RuBP.'),
  ('ap-topic-bio-chem_q9', 'ap-topic-bio-chem', 9, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'Which polymer is formed by $\beta$-1,4-glycosidic linkages that human digestive enzymes cannot hydrolyze?', '["Cellulose","Starch (amylose)","Glycogen","Amylopectin"]'::jsonb, 'Cellulose consists of glucose monomers joined by $\beta$-1,4-glycosidic linkages. Humans lack cellulase enzymes capable of cleaving $\beta$-linkages, unlike the $\alpha$-1,4-linkages in starch and glycogen.'),
  ('ap-topic-bio-chem_q10', 'ap-topic-bio-chem', 10, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'Why does an extreme increase in temperature above an enzyme''s optimum lead to a dramatic decline in reaction rate?', '["Thermal agitation disrupts non-covalent bonds (hydrogen and ionic bonds), causing denaturation of the active site","The activation energy of the chemical reaction is permanently lowered","Substrate molecules are converted into non-competitive inhibitors","Peptide bonds are immediately cleaved into individual amino acids"]'::jsonb, 'Excess thermal energy disrupts weak intermolecular interactions (hydrogen bonds, ionic interactions, hydrophobic interactions) holding the tertiary structure, causing active site denaturation.'),
  ('ap-topic-bio-chem_q11', 'ap-topic-bio-chem', 11, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'Under anaerobic conditions in human muscle tissue, what is the primary biochemical purpose of converting pyruvate to lactate via fermentation?', '["To regenerate $NAD^+$ from $NADH$ so that glycolysis can continue producing ATP","To directly generate 2 additional ATP molecules per glucose","To transport oxygen into the mitochondria","To lower intracellular pH to prevent fatigue"]'::jsonb, 'Glycolysis requires oxidized $NAD^+$ to oxidize glyceraldehyde-3-phosphate. In the absence of oxygen as a terminal electron acceptor, lactate dehydrogenase oxidizes $NADH$ back to $NAD^+$, allowing substrate-level phosphorylation in glycolysis to persist.'),
  ('ap-topic-bio-chem_q12', 'ap-topic-bio-chem', 12, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'Which biological molecule is amphipathic, possessing both a hydrophilic head and two hydrophobic tails?', '["Phospholipid","Triglyceride","Cholesterol","Nucleotide"]'::jsonb, 'A phospholipid consists of a hydrophilic glycerol-phosphate head group and two hydrophobic fatty acid hydrocarbon tails, forming the bilayer foundation of biological membranes.'),
  ('ap-topic-bio-chem_q13', 'ap-topic-bio-chem', 13, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'What type of chemical reaction joins two amino acids together with the removal of a water molecule?', '["Dehydration synthesis (condensation)","Hydrolysis","Decarboxylation","Hydrogenation"]'::jsonb, 'A peptide bond forms between the carboxyl group of one amino acid and the amino group of another via dehydration synthesis (condensation reaction), releasing a molecule of $H_2O$.'),
  ('ap-topic-bio-chem_q14', 'ap-topic-bio-chem', 14, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'How do uncoupling agents (such as 2,4-dinitrophenol, DNP) affect mitochondrial respiration and ATP synthesis?', '["They dissipate the proton gradient across the inner mitochondrial membrane, allowing oxygen consumption to continue while halting ATP production and releasing energy as heat","They directly inhibit Complex I, halting all electron transport and oxygen consumption","They block the binding of pyruvate to the Krebs cycle enzymes","They bind irreversibly to the active site of ATP synthase"]'::jsonb, 'DNP is a lipid-soluble proton ionophore that shuttles $H^+$ across the inner membrane, collapsing the proton-motive force. The electron transport chain runs rapidly, consuming oxygen and releasing free energy as heat without producing ATP.'),
  ('ap-topic-bio-chem_q15', 'ap-topic-bio-chem', 15, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'Which nucleic acid base is found exclusively in RNA and pairs with adenine?', '["Uracil","Thymine","Cytosine","Guanine"]'::jsonb, 'Uracil replaces thymine in RNA molecules, pairing with adenine via two hydrogen bonds.'),
  ('ap-topic-bio-chem_q16', 'ap-topic-bio-chem', 16, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'What is the net yield of ATP, NADH, and pyruvate per glucose molecule during glycolysis?', '["2 ATP, 2 NADH, 2 Pyruvate","4 ATP, 2 NADH, 2 Pyruvate","2 ATP, 4 NADH, 1 Pyruvate","36 ATP, 10 NADH, 2 Pyruvate"]'::jsonb, 'Glycolysis consumes 2 ATP in the investment phase and produces 4 ATP and 2 NADH in the payoff phase, resulting in a net yield of 2 ATP, 2 NADH, and 2 pyruvate molecules per glucose.'),
  ('ap-topic-bio-chem_q17', 'ap-topic-bio-chem', 17, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'How does allosteric feedback inhibition regulate metabolic pathways efficiently?', '["The end product of the pathway binds to an allosteric site on an early regulatory enzyme, inhibiting its activity when product concentration is high","The starting substrate permanently destroys the final enzyme in the pathway","The end product competitively blocks the active site of all enzymes in the cell","The pathway reverses direction to consume excess ATP"]'::jsonb, 'Feedback inhibition occurs when the ultimate end product binds allosterically (non-competitively) to the pathway''s committed enzyme, causing a conformational change that shuts down unnecessary synthesis.'),
  ('ap-topic-bio-chem_q18', 'ap-topic-bio-chem', 18, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'What structural feature allows saturated fatty acids to pack closely together, making them solid at room temperature?', '["The absence of carbon-carbon double bonds, yielding straight hydrocarbon chains","The presence of multiple cis-double bonds creating kinks in the chain","The presence of ionic phosphate heads linking adjacent tails","Their cyclic aromatic ring structures"]'::jsonb, 'Saturated fatty acids contain only single C-C bonds, resulting in straight conformations that maximize van der Waals contacts, raising melting temperatures so they are solid at room temperature.'),
  ('ap-topic-bio-chem_q19', 'ap-topic-bio-chem', 19, false, 'A', 'Chemistry of Life & Cellular Energetics', 'medium', 'What primary role does cholesterol play in mammalian cell membranes?', '["It acts as a fluidity buffer, stabilizing fluidity at high temperatures and preventing tight packing at low temperatures","It actively pumps glucose into the cell against its gradient","It forms channels for rapid water diffusion","It functions as the primary receptor for peptide hormones"]'::jsonb, 'Cholesterol intercalates between phospholipids. At elevated temperatures, its rigid steroid rings restrain phospholipid movement; at low temperatures, it prevents close packing, maintaining membrane fluidity.'),
  ('ap-topic-bio-chem_q20', 'ap-topic-bio-chem', 20, false, 'A', 'Chemistry of Life & Cellular Energetics', 'hard', 'During the light reactions of photosynthesis, what is the source of energy that directly drives the active transport of protons into the thylakoid lumen?', '["The stepwise exergonic transfer of electrons through the cytochrome $b_6f$ electron transport chain","The direct hydrolysis of ATP in the stroma","The spontaneous diffusion of $CO_2$ gas through stomata","The breakdown of glucose in the cytoplasm"]'::jsonb, 'As electrons move down the photosynthetic electron transport chain from PSII through plastoquinone to the cytochrome $b_6f$ complex, the released free energy pumps protons ($H^+$) into the thylakoid lumen, generating the proton gradient for ATP synthase.'),
  ('ap-topic-chem-structure_q1', 'ap-topic-chem-structure', 1, false, 'C', 'Bonding', 'medium', 'What is the hybridization of the central atom in $CH_4$?', '["sp","sp2","sp3","sp3d"]'::jsonb, 'Methane has 4 electron domains, forming $sp^3$ hybrid orbitals.'),
  ('ap-topic-chem-structure_q2', 'ap-topic-chem-structure', 2, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which element has the electron configuration $[\text{Ar}] 4s^2 3d^{10} 4p^3$?', '["Arsenic (As)","Phosphorus (P)","Selenium (Se)","Germanium (Ge)"]'::jsonb, 'Argon has atomic number 18. Adding electrons: $18 + 2 (4s) + 10 (3d) + 3 (4p) = 33$ electrons. Element 33 is Arsenic (As).'),
  ('ap-topic-chem-structure_q3', 'ap-topic-chem-structure', 3, false, 'A', 'Atomic Structure & Bonding', 'medium', 'What is the molecular geometry and hybridization of the central atom in sulfur tetrafluoride ($SF_4$)?', '["See-saw geometry, $sp^3d$ hybridization","Tetrahedral geometry, $sp^3$ hybridization","Square planar geometry, $sp^3d^2$ hybridization","Trigonal bipyramidal geometry, $sp^3d$ hybridization"]'::jsonb, 'Sulfur has 6 valence electrons; 4 form single bonds to fluorine and 2 remain as 1 lone pair. Steric number is $4 + 1 = 5$, giving $sp^3d$ hybridization and trigonal bipyramidal electron geometry. With 1 equatorial lone pair, the molecular shape is see-saw.'),
  ('ap-topic-chem-structure_q4', 'ap-topic-chem-structure', 4, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which of the following atoms has the highest first ionization energy?', '["Fluorine (F)","Oxygen (O)","Nitrogen (N)","Carbon (C)"]'::jsonb, 'First ionization energy increases across a period from left to right due to increasing effective nuclear charge ($Z_{\text{eff}}$) pulling electrons closer to the nucleus. Among C, N, O, and F, Fluorine has the highest first ionization energy ($1681\text{ kJ/mol}$).'),
  ('ap-topic-chem-structure_q5', 'ap-topic-chem-structure', 5, false, 'A', 'Atomic Structure & Bonding', 'hard', 'Why is the first ionization energy of oxygen ($1314\text{ kJ/mol}$) slightly lower than that of nitrogen ($1402\text{ kJ/mol}$)?', '["Oxygen has a paired electron in one of its $2p$ orbitals, and the resulting electron-electron repulsion makes it easier to remove","Nitrogen has a higher effective nuclear charge than oxygen","Oxygen has a smaller atomic radius, shielding its valence electrons","Nitrogen''s valence electrons are in the $3s$ subshell"]'::jsonb, 'Nitrogen has a half-filled $2p^3$ configuration with three unpaired electrons in separate orbitals. Oxygen ($2p^4$) has one doubly occupied $2p$ orbital. The electrostatic repulsion between the two paired electrons in that orbital raises the energy of the electron, making it easier to remove.'),
  ('ap-topic-chem-structure_q6', 'ap-topic-chem-structure', 6, false, 'A', 'Atomic Structure & Bonding', 'medium', 'What is the formal charge on the central sulfur atom in the sulfate ion ($SO_4^{2-}$) when drawn with an expanded octet having two $S=O$ double bonds and two $S-O^-$ single bonds?', '["0","+2","+1","-2"]'::jsonb, 'Sulfur has 6 valence electrons. In this structure, sulfur has 6 bonding domains (2 double bonds = 4 bonds, 2 single bonds = 2 bonds, total 6 shared pairs) and 0 lone pairs. $\text{Formal Charge} = V - N_{\text{lone}} - \frac{1}{2}N_{\text{bonding}} = 6 - 0 - 6 = 0$.'),
  ('ap-topic-chem-structure_q7', 'ap-topic-chem-structure', 7, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which of the following species is nonpolar despite containing polar covalent bonds?', '["$BF_3$ (boron trifluoride)","$NF_3$ (nitrogen trifluoride)","$H_2O$ (water)","$SO_2$ (sulfur dioxide)"]'::jsonb, '$BF_3$ has trigonal planar molecular geometry ($120^\circ$ bond angles). The three equal B-F bond dipoles point symmetrically in a plane and vectorially sum to zero, resulting in a net molecular dipole moment of zero.'),
  ('ap-topic-chem-structure_q8', 'ap-topic-chem-structure', 8, false, 'A', 'Atomic Structure & Bonding', 'hard', 'In photoelectron spectroscopy (PES), the spectrum of an unknown neutral atom shows five peaks with binding energies of $193\text{ MJ/mol}$, $17.2\text{ MJ/mol}$, $12.1\text{ MJ/mol}$, $1.09\text{ MJ/mol}$, and $0.59\text{ MJ/mol}$, with relative peak heights of 2 : 2 : 6 : 2 : 1. Identify the element.', '["Aluminum (Al)","Sodium (Na)","Magnesium (Mg)","Silicon (Si)"]'::jsonb, 'The peaks correspond to subshells ordered by decreasing binding energy: $1s^2 (193)$, $2s^2 (17.2)$, $2p^6 (12.1)$, $3s^2 (1.09)$, and $3p^1 (0.59)$. The electron configuration is $1s^2 2s^2 2p^6 3s^2 3p^1$, which corresponds to atomic number 13, Aluminum (Al).'),
  ('ap-topic-chem-structure_q9', 'ap-topic-chem-structure', 9, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which of the following compounds has the highest lattice energy?', '["MgO","NaCl","NaF","CaO"]'::jsonb, 'Lattice energy is governed by Coulomb''s Law: $E_{\text{lattice}} \propto \frac{|q_1 q_2|}{r_0}$. In MgO, charges are $+2$ and $-2$ (product $= 4$), compared to $+1/-1$ in NaCl and NaF. Between MgO and CaO, $Mg^{2+}$ has a smaller ionic radius than $Ca^{2+}$, resulting in a shorter internuclear distance and the highest lattice energy.'),
  ('ap-topic-chem-structure_q10', 'ap-topic-chem-structure', 10, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which type of intermolecular force is primarily responsible for the unusually high boiling point of ethanol ($CH_3CH_2OH$, $78^\circ\text{C}$) compared to dimethyl ether ($CH_3OCH_3$, $-24^\circ\text{C}$)?', '["Hydrogen bonding","London dispersion forces","Ion-dipole forces","Covalent network bonding"]'::jsonb, 'Both ethanol and dimethyl ether have identical chemical formulas ($C_2H_6O$) and molar masses ($46\text{ g/mol}$). Ethanol possesses an -OH group capable of intermolecular hydrogen bonding, which requires significantly more thermal energy to break.'),
  ('ap-topic-chem-structure_q11', 'ap-topic-chem-structure', 11, false, 'A', 'Atomic Structure & Bonding', 'medium', 'How many sigma ($\sigma$) and pi ($\pi$) bonds are present in a molecule of ethyne (acetylene, $H-C\equiv C-H$)?', '["3 $\\sigma$ bonds and 2 $\\pi$ bonds","2 $\\sigma$ bonds and 3 $\\pi$ bonds","1 $\\sigma$ bond and 2 $\\pi$ bonds","5 $\\sigma$ bonds and 0 $\\pi$ bonds"]'::jsonb, 'Each single C-H bond is 1 $\sigma$ bond (2 total). The triple bond $C\equiv C$ consists of 1 $\sigma$ bond and 2 $\pi$ bonds. Total: $2 + 1 = 3$ $\sigma$ bonds and 2 $\pi$ bonds.'),
  ('ap-topic-chem-structure_q12', 'ap-topic-chem-structure', 12, false, 'A', 'Atomic Structure & Bonding', 'hard', 'What is the molecular geometry of the triiodide ion ($I_3^-$)?', '["Linear","Bent","Trigonal planar","T-shaped"]'::jsonb, 'The central iodine has 7 valence electrons, shares 2 single bonds with the outer iodines, and accommodates 1 extra negative charge: $7 + 2 + 1 = 10$ valence electrons, or 5 electron pairs (2 bonding pairs and 3 equatorial lone pairs). This trigonal bipyramidal electron domain geometry places lone pairs equatorially to minimize repulsion, yielding a linear molecular shape ($180^\circ$).'),
  ('ap-topic-chem-structure_q13', 'ap-topic-chem-structure', 13, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Arrange the following ions in order of decreasing ionic radius: $S^{2-}, Cl^-, K^+, Ca^{2+}$.', '["$S^{2-} > Cl^- > K^+ > Ca^{2+}$","$Ca^{2+} > K^+ > Cl^- > S^{2-}$","$Cl^- > S^{2-} > Ca^{2+} > K^+$","$K^+ > Ca^{2+} > S^{2-} > Cl^-$"]'::jsonb, 'These ions are isoelectronic, each possessing 18 electrons ($[\text{Ar}]$ configuration). As nuclear charge ($Z$) increases ($S: 16, Cl: 17, K: 19, Ca: 20$), the increasing positive charge pulls the electron cloud tighter, decreasing ionic radius: $S^{2-} > Cl^- > K^+ > Ca^{2+}$.'),
  ('ap-topic-chem-structure_q14', 'ap-topic-chem-structure', 14, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Why does silicon dioxide ($SiO_2$) have a very high melting point ($> 1600^\circ\text{C}$) while carbon dioxide ($CO_2$) is a gas at room temperature?', '["$SiO_2$ forms a 3-dimensional covalent network solid with strong Si-O bonds, whereas $CO_2$ consists of discrete small molecules held only by weak London dispersion forces","$SiO_2$ is an ionic lattice of $Si^{4+}$ and $O^{2-}$ ions","$CO_2$ contains only weak single bonds while $SiO_2$ contains quadruple bonds","Silicon has a much lower atomic mass than carbon"]'::jsonb, '$SiO_2$ forms a covalent network lattice where every silicon atom is bonded tetrahedrally to 4 oxygen atoms. Melting requires breaking strong covalent bonds throughout the macroscopic crystal. In contrast, $CO_2$ forms discrete linear molecules held together only by weak London dispersion forces.'),
  ('ap-topic-chem-structure_q15', 'ap-topic-chem-structure', 15, false, 'A', 'Atomic Structure & Bonding', 'hard', 'According to Hund''s rule and the Pauli exclusion principle, what is the number of unpaired electrons in a ground-state gaseous iron atom ($Fe$, $Z = 26$)?', '["4","2","6","0"]'::jsonb, 'The electron configuration of Fe is $[\text{Ar}] 4s^2 3d^6$. The five degenerate $3d$ orbitals are populated by 6 electrons: one orbital has a paired spin, and the other four orbitals contain a single unpaired electron each ($4 \times 1 = 4$).'),
  ('ap-topic-chem-structure_q16', 'ap-topic-chem-structure', 16, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Under which conditions does a real gas deviate most significantly from ideal behavior described by the Ideal Gas Law ($PV = nRT$)?', '["High pressure and low temperature","Low pressure and high temperature","Moderate pressure and room temperature","Low pressure and high molar mass"]'::jsonb, 'At high pressures, the volume occupied by the gas molecules themselves becomes non-negligible compared to total volume. At low temperatures, molecules move slowly, allowing attractive intermolecular forces to reduce impact force against container walls.'),
  ('ap-topic-chem-structure_q17', 'ap-topic-chem-structure', 17, false, 'A', 'Atomic Structure & Bonding', 'medium', 'What is the bond order of the carbon-oxygen bonds in the carbonate ion ($CO_3^{2-}$)?', '["4/3 (or 1.33)","1","2","3/2 (or 1.50)"]'::jsonb, 'The carbonate ion has 3 equivalent resonance structures, sharing 4 total pairs of bonding electrons (one double bond and two single bonds) across 3 C-O bond locations. Bond order $= \frac{4}{3} \approx 1.33$.'),
  ('ap-topic-chem-structure_q18', 'ap-topic-chem-structure', 18, false, 'A', 'Atomic Structure & Bonding', 'hard', 'A mixture contains $0.20\text{ mol}$ of $He$ and $0.80\text{ mol}$ of $Ar$ in a rigid container at total pressure $5.0\text{ atm}$. What is the partial pressure of helium?', '["1.0 atm","0.2 atm","4.0 atm","2.5 atm"]'::jsonb, 'Dalton''s Law of Partial Pressures: $P_{\text{He}} = X_{\text{He}} P_{\text{total}}$. Mole fraction $X_{\text{He}} = \frac{0.20}{0.20 + 0.80} = 0.20$. Thus $P_{\text{He}} = (0.20)(5.0\text{ atm}) = 1.0\text{ atm}$.'),
  ('ap-topic-chem-structure_q19', 'ap-topic-chem-structure', 19, false, 'A', 'Atomic Structure & Bonding', 'medium', 'Which of the following molecules has a square planar molecular geometry?', '["$XeF_4$","$CH_4$","$SF_4$","$BF_4^-$"]'::jsonb, 'Xenon in $XeF_4$ has 8 valence electrons, forming 4 single bonds with fluorine and retaining 2 lone pairs ($4 + 2 = 6$ electron pairs, octahedral electron domain geometry). The two lone pairs position trans to each other, resulting in a square planar molecular geometry.'),
  ('ap-topic-chem-structure_q20', 'ap-topic-chem-structure', 20, false, 'A', 'Atomic Structure & Bonding', 'hard', 'Why does boiling point increase systematically in the noble gas group from Helium ($-269^\circ\text{C}$) to Xenon ($-108^\circ\text{C}$)?', '["Heavier noble gases possess more electrons over a larger electron cloud, increasing polarizability and London dispersion forces","Heavier noble gases form stronger permanent dipole moments","Heavier noble gases participate in extensive hydrogen bonding","Heavier noble gases have smaller atomic radii"]'::jsonb, 'Noble gases are nonpolar monatomic species held only by London dispersion forces. Down the group, the number of electrons and atomic radius increase, creating a more diffuse, highly polarizable electron cloud that generates stronger temporary dipole interactions.')
INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-env-ecosys_q1', 'ap-topic-env-ecosys', 1, false, 'B', 'Ecology', 'easy', 'Which biome is characterized by permafrost and low-growing vegetation?', '["Taiga","Tundra","Savanna","Temperate Forest"]'::jsonb, 'Tundra features permanently frozen subsoil (permafrost).'),
  ('ap-topic-env-ecosys_q2', 'ap-topic-env-ecosys', 2, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'According to the 10% rule of ecological energy transfer, if producers in an ecosystem capture $100,000\text{ kcal}$ of solar energy into net primary productivity, how much energy is typically available to secondary consumers?', '["1,000 kcal","10,000 kcal","100 kcal","100,000 kcal"]'::jsonb, 'Producers: $100,000\text{ kcal}$. Primary consumers receive $10\%$: $10,000\text{ kcal}$. Secondary consumers receive $10\%$ of primary consumer energy: $1,000\text{ kcal}$.'),
  ('ap-topic-env-ecosys_q3', 'ap-topic-env-ecosys', 3, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Which biogeochemical cycle lacks a significant gaseous atmospheric reservoir and cycles primarily through rocks, soil, and sediments?', '["Phosphorus cycle","Carbon cycle","Nitrogen cycle","Sulfur cycle"]'::jsonb, 'Unlike carbon, nitrogen, and sulfur, phosphorus does not enter the atmosphere in significant gaseous forms. Its major geological reservoir is phosphate-bearing sedimentary rock, released slowly by weathering.'),
  ('ap-topic-env-ecosys_q4', 'ap-topic-env-ecosys', 4, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'In the nitrogen cycle, which biological process converts atmospheric nitrogen ($N_2$) into biologically usable ammonia ($NH_3$ or $NH_4^+$)?', '["Nitrogen fixation","Denitrification","Nitrification","Assimilation"]'::jsonb, 'Nitrogen fixation is the reduction of atmospheric $N_2$ gas into ammonia ($NH_3$) or ammonium ($NH_4^+$), carried out by specialized nitrogen-fixing bacteria (such as Rhizobium in legume root nodules).'),
  ('ap-topic-env-ecosys_q5', 'ap-topic-env-ecosys', 5, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'According to the Theory of Island Biogeography proposed by MacArthur and Wilson, which island will have the highest equilibrium species richness?', '["A large island located close to the mainland","A small island located close to the mainland","A large island located far from the mainland","A small island located far from the mainland"]'::jsonb, 'Island biogeography predicts that immigration rates are highest on islands close to the mainland, while extinction rates are lowest on large islands due to greater habitat area and resources. Thus, large, near islands maintain the highest equilibrium biodiversity.'),
  ('ap-topic-env-ecosys_q6', 'ap-topic-env-ecosys', 6, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'What type of ecological succession occurs on bare rock exposed after a glacier retreats or a newly formed volcanic lava flow?', '["Primary succession","Secondary succession","Climax succession","Cyclic succession"]'::jsonb, 'Primary succession begins in a virtually lifeless area where no soil exists (e.g., bare rock). Pioneer species like lichens and mosses weather rock to form the initial soil layer.'),
  ('ap-topic-env-ecosys_q7', 'ap-topic-env-ecosys', 7, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Which of the following is an example of an ecosystem "regulating service"?', '["Wetlands filtering contaminants and controlling storm floodwaters","Harvesting timber from forests for home construction","Recreational ecotourism and aesthetic inspiration in national parks","Soil formation and primary production through photosynthesis"]'::jsonb, 'Ecosystem services are classified into: provisioning (goods like timber), regulating (natural processes like flood control, water filtration, climate moderation), cultural (recreation), and supporting (soil formation).'),
  ('ap-topic-env-ecosys_q8', 'ap-topic-env-ecosys', 8, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'Which characteristics are typically associated with $K$-selected species?', '["Large body size, late reproductive maturity, few offspring per brood, and high parental care","Small body size, rapid sexual maturity, high fecundity, and zero parental investment","High reproductive rate that frequently exceeds environmental carrying capacity","Short lifespans with high infant mortality rates (Type III survivorship)"]'::jsonb, '$K$-selected species thrive near carrying capacity ($K$). They invest heavily in a small number of offspring, exhibiting prolonged maturation, parental care, and Type I survivorship curves.'),
  ('ap-topic-env-ecosys_q9', 'ap-topic-env-ecosys', 9, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'What is the sequence of events leading to cultural eutrophication in aquatic ecosystems after agricultural runoff?', '["Nutrient enrichment (N & P) -> algal bloom -> algae die and sink -> aerobic bacteria decompose algae, consuming dissolved oxygen -> hypoxia/fish kill","Toxins kill fish immediately -> dissolved oxygen spikes -> algae overgrow -> water turns clear","Water temperature drops -> fish migrate -> plant growth stops -> oxygen depletion","Nutrients evaporate -> water salinity increases -> aquatic plants dry up"]'::jsonb, 'Excess nitrogen and phosphorus spur massive algal blooms. When algae die, decomposers consume dissolved oxygen through cellular respiration, causing severe hypoxia (dead zones).'),
  ('ap-topic-env-ecosys_q10', 'ap-topic-env-ecosys', 10, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'A keystone species is defined as a species that:', '["Has a disproportionately large impact on community structure and biodiversity relative to its abundance or biomass","Has the highest total biomass in the ecosystem","Is the most abundant primary producer in a food web","Was introduced from another continent and rapidly outcompetes native organisms"]'::jsonb, 'A keystone species (e.g., sea otters, wolves) exerts pivotal regulatory control over ecosystem balance and community diversity despite low numerical abundance.'),
  ('ap-topic-env-ecosys_q11', 'ap-topic-env-ecosys', 11, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Which survivorship curve is characteristic of marine invertebrates (such as oysters) that produce millions of eggs, most of which die as larvae?', '["Type III survivorship","Type I survivorship","Type II survivorship","Type IV survivorship"]'::jsonb, 'Type III survivorship exhibits very high mortality among early life stages, with high survival rates for the few individuals reaching adulthood.'),
  ('ap-topic-env-ecosys_q12', 'ap-topic-env-ecosys', 12, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'How do Net Primary Productivity (NPP) and Gross Primary Productivity (GPP) mathematically relate?', '["$\\text{NPP} = \\text{GPP} - R_{\\text{respiration}}$","$\\text{NPP} = \\text{GPP} + R_{\\text{respiration}}$","$\\text{NPP} = \\text{GPP} / R_{\\text{respiration}}$","$\\text{NPP} = R_{\\text{respiration}} - \\text{GPP}$"]'::jsonb, 'Gross Primary Productivity (GPP) is the total rate at which solar energy is captured by producers. Producers use part of this energy for cellular respiration ($R$). NPP is the remaining biomass available to consumers: $\text{NPP} = \text{GPP} - R$.'),
  ('ap-topic-env-ecosys_q13', 'ap-topic-env-ecosys', 13, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Why are invasive generalist species often able to rapidly outcompete native specialist species in disturbed environments?', '["They have wide ecological tolerances, flexible diets, rapid reproductive rates, and lack native co-evolved predators or parasites","They require highly specific nesting microclimates found only in disturbed areas","They have smaller geographic ranges and low genetic diversity","They do not require food or water to survive"]'::jsonb, 'Generalist invasive species tolerate broad environmental conditions, exploit diverse food sources, reproduce quickly, and benefit from "enemy release" (absence of natural predators and diseases in new ranges).'),
  ('ap-topic-env-ecosys_q14', 'ap-topic-env-ecosys', 14, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Which of the following processes removes carbon dioxide directly from the atmosphere and sequesters it in biological biomass?', '["Photosynthesis by terrestrial plants and phytoplankton","Cellular respiration by decomposers","Combustion of fossil fuels","Volcanic degassing"]'::jsonb, 'Photosynthetic autotrophs (plants, algae, cyanobacteria) absorb atmospheric $CO_2$ and convert it into organic carbohydrates, sequestering carbon in living tissue.'),
  ('ap-topic-env-ecosys_q15', 'ap-topic-env-ecosys', 15, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'Two forests both contain 100 trees distributed among 4 species. Forest A has 25 trees of each species. Forest B has 85 trees of Species 1, and 5 trees each of Species 2, 3, and 4. Which forest has greater biodiversity and why?', '["Forest A, because both have equal species richness (4 species) but Forest A has much higher species evenness","Forest B, because Species 1 dominates the biomass","Both forests have identical biodiversity because both have 100 trees and 4 species","Forest B, because high dominance indicates superior ecological fitness"]'::jsonb, 'Biodiversity incorporates both richness (number of different species) and evenness (relative abundance). Both forests have a richness of 4, but Forest A has maximal evenness (25% each), giving it a significantly higher Shannon-Wiener diversity index.'),
  ('ap-topic-env-ecosys_q16', 'ap-topic-env-ecosys', 16, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'What ecological role is played by mycorrhizal fungi in terrestrial ecosystems?', '["They form mutualistic symbiotic associations with plant roots, enhancing water and phosphorus absorption in exchange for photosynthesized sugars","They act as pathogenic parasites that kill pioneer plant species during primary succession","They fix atmospheric nitrogen into nitrates in aquatic biomes","They pollinate flowering angiosperms"]'::jsonb, 'Mycorrhizae are mutualisms where fungal hyphae vastly expand the root surface area for water and mineral nutrient (especially phosphate) uptake, while the host plant supplies organic carbohydrates.'),
  ('ap-topic-env-ecosys_q17', 'ap-topic-env-ecosys', 17, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'In a marine ecosystem, a persistent synthetic pesticide (DDT) is found at $0.00005\text{ ppm}$ in seawater, $0.04\text{ ppm}$ in zooplankton, $0.5\text{ ppm}$ in small fish, and $25\text{ ppm}$ in osprey (apex predator). This phenomenon is known as:', '["Biomagnification","Bioaccumulation","Bioremediation","Biomimicry"]'::jsonb, 'Biomagnification is the progressive increase in the concentration of fat-soluble, non-biodegradable toxins in the tissues of organisms at successively higher trophic levels.'),
  ('ap-topic-env-ecosys_q18', 'ap-topic-env-ecosys', 18, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'Which terrestrial biome is characterized by permafrost, extremely low precipitation, dwarf vegetation, and brief summer growing seasons?', '["Tundra","Taiga (Boreal forest)","Temperate deciduous forest","Chaparral"]'::jsonb, 'The arctic tundra features permanently frozen subsoil (permafrost), cold desert-like precipitation, low temperatures, and low-growing mosses, lichens, and sedges.'),
  ('ap-topic-env-ecosys_q19', 'ap-topic-env-ecosys', 19, false, 'A', 'Ecosystems & Biodiversity', 'medium', 'What is the competitive exclusion principle (Gause''s Law)?', '["Two species competing for the exact same limiting resources cannot stably coexist if other ecological factors remain constant","Predators and prey always maintain equal population numbers","Mutualistic species cannot inhabit the same geographic range","Invasive species always eliminate all native organisms within two years"]'::jsonb, 'The competitive exclusion principle states that two species with identical ecological niches cannot coexist indefinitely; the species with even a slight reproductive advantage will outcompete and exclude the other.'),
  ('ap-topic-env-ecosys_q20', 'ap-topic-env-ecosys', 20, false, 'A', 'Ecosystems & Biodiversity', 'hard', 'How does habitat fragmentation typically affect species populations residing within isolated forest fragments?', '["It increases edge effects, decreases gene flow between subpopulations, and heightens vulnerability to local extinction","It increases total genetic diversity by forcing populations to adapt to agricultural edges","It eliminates all edge habitat and increases interior core forest area","It universally increases immigration rates between fragments"]'::jsonb, 'Fragmentation divides continuous habitat into smaller parcels, increasing the perimeter-to-area ratio (edge effects: more wind, light, invasive species) and isolating gene pools, which increases inbreeding and extinction risk.')
